// Turn the ES-module sources into one classic script, app.bundle.js.
//
// Chrome blocks <script type="module"> on file://, so a page opened by
// double-click needs a classic script. The sources stay as readable modules;
// this script only re-packages them. Each file becomes a function scope that
// receives exactly the names it imports and returns exactly the names it
// exports, which is how modules behave, so same-named private helpers in
// different files (like `money`) never collide.
//
//   node build-bundle.mjs

import { readFileSync, writeFileSync } from "node:fs";

// Dependency order: a file may only import from files listed before it.
const order = ["viz.js", "book.js", "charts.js", "charts2.js", "app.js"];

const IMPORT = /^import\s+\{([\s\S]*?)\}\s+from\s+["']\.\/([^"']+)["'];?[ \t]*$/gm;
const EXPORT_DECL = /^export\s+((?:async\s+)?(?:function|const|let|class)\s+([A-Za-z_$][\w$]*))/gm;

const exportsOf = new Map(); // file -> Set of exported names
const chunks = [];

for (const file of order) {
  let src = readFileSync(file, "utf8");

  const imports = [];
  src = src.replace(IMPORT, (_, names, from) => {
    if (!exportsOf.has(from)) throw new Error(`${file} imports ${from}, which is not bundled before it`);
    for (const n of names.split(",").map((s) => s.trim()).filter(Boolean)) {
      if (!exportsOf.get(from).has(n)) throw new Error(`${file} imports "${n}" but ${from} does not export it`);
      imports.push(`${n} = __m[${JSON.stringify(from)}].${n}`);
    }
    return "";
  });
  if (/^import\s/m.test(src)) throw new Error(`${file}: an import statement was not understood`);

  const names = [];
  src = src.replace(EXPORT_DECL, (_, decl, name) => {
    names.push(name);
    return decl;
  });
  exportsOf.set(file, new Set(names));

  const head = imports.length ? `const ${imports.join(",\n  ")};\n` : "";
  const tail = names.length ? `\nreturn { ${names.join(", ")} };` : "";
  chunks.push(`__m[${JSON.stringify(file)}] = (function () {\n${head}${src}${tail}\n})();`);
}

writeFileSync(
  "app.bundle.js",
  "// Generated by build-bundle.mjs from " + order.join(", ") + ". Do not edit.\n" +
    "(function () {\n\"use strict\";\nconst __m = {};\n\n" + chunks.join("\n\n") + "\n})();\n",
);
console.log(`wrote app.bundle.js from ${order.length} modules`);
